<?php
require_once __DIR__ . '/../assets/php/layout.php';
require_admin();
$message='';$device=null;
try{$pdo=db();$device=get_active_device($pdo);if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$deviceId=filter_input(INPUT_POST,'device_id',FILTER_VALIDATE_INT);$values=[];foreach(['temp_min','temp_max','humidity_min','humidity_max'] as $field){$v=filter_input(INPUT_POST,$field,FILTER_VALIDATE_FLOAT);if($v===false||$v===null)throw new RuntimeException('Enter valid temperature and humidity ranges.');$values[]=$v;}if($values[0]>=$values[1]||$values[2]>=$values[3])throw new RuntimeException('Each minimum must be below its maximum.');$airWarn=filter_input(INPUT_POST,'air_warning_adc',FILTER_VALIDATE_INT);$airAlert=filter_input(INPUT_POST,'air_alert_adc',FILTER_VALIDATE_INT);$light=filter_input(INPUT_POST,'light_on_adc',FILTER_VALIDATE_INT);foreach([$airWarn,$airAlert,$light] as $v)if($v!==null&&$v!==false&&($v<0||$v>4095))throw new RuntimeException('Raw ADC thresholds must be from 0 to 4095.');$stmt=$pdo->prepare('UPDATE devices SET temp_min=?,temp_max=?,humidity_min=?,humidity_max=?,air_warning_adc=?,air_alert_adc=?,light_on_adc=? WHERE id=?');$stmt->execute([...$values,$airWarn?:null,$airAlert?:null,$light?:null,$deviceId]);log_activity($pdo,(int)$_SESSION['user_id'],'thresholds_updated',(string)$deviceId);$message='Thresholds saved.';$device=get_active_device($pdo);}}catch(Throwable $exception){$message=$exception instanceof RuntimeException?$exception->getMessage():database_error_message();}
layout_start('Thresholds','admin');
?>
<?php if($message): ?><p class="inline-notice"><?= e($message) ?></p><?php endif; ?>
<section class="content-card"><h2>Sensor thresholds</h2><?php if(!$device): ?><p class="empty-state">Register a device before setting its thresholds.</p><?php else: ?><p>MQ-135 and LDR values stay uncalibrated until measured in the room.</p><form class="settings-form" method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="device_id" value="<?= (int)$device['id'] ?>"><div class="form-grid"><label>Temperature minimum (°C)<input type="number" step="0.1" name="temp_min" value="<?= e((string)$device['temp_min']) ?>" required></label><label>Temperature maximum (°C)<input type="number" step="0.1" name="temp_max" value="<?= e((string)$device['temp_max']) ?>" required></label><label>Humidity minimum (%)<input type="number" step="0.1" name="humidity_min" value="<?= e((string)$device['humidity_min']) ?>" required></label><label>Humidity maximum (%)<input type="number" step="0.1" name="humidity_max" value="<?= e((string)$device['humidity_max']) ?>" required></label><label>Air warning ADC (optional)<input type="number" min="0" max="4095" name="air_warning_adc" value="<?= e((string)$device['air_warning_adc']) ?>"></label><label>Air alert ADC (optional)<input type="number" min="0" max="4095" name="air_alert_adc" value="<?= e((string)$device['air_alert_adc']) ?>"></label><label>Light on ADC (optional)<input type="number" min="0" max="4095" name="light_on_adc" value="<?= e((string)$device['light_on_adc']) ?>"></label></div><button class="button-primary" type="submit">Save thresholds</button></form><?php endif; ?></section>
<?php layout_end(); ?>

